SELECT *
FROM (
         SELECT t.*, ROW_NUMBER() OVER (ORDER BY t."record_id" DESC) AS rn
         FROM (
                  SELECT * FROM BOOKMAN."borrow_record"
              ) t
     ) rt
WHERE rt.rn >= #{start} AND rt.rn <= #{end}

SELECT *
FROM (
         SELECT t.*, ROW_NUMBER() OVER (ORDER BY t."record_id" DESC) AS rn
         FROM (
                  SELECT "record_id", "user_id", "uname", "borrow_record"."book_id", "book_title", "borrow_date", "return_date"
                  FROM BOOKMAN."borrow_record"
                           left join BOOKMAN."user" on "user"."uid" = "borrow_record"."user_id"
                           left join BOOKMAN."book" on "book"."book_id" = "borrow_record"."book_id"
                  WHERE "user_id" = #{userId}
              ) t
     ) rt
WHERE rt.rn >= #{start} AND rt.rn <= #{end}

SELECT *
FROM (
         SELECT t.*, ROW_NUMBER() OVER (ORDER BY t."record_id" DESC) AS rn
         FROM (
                  SELECT "record_id", "user_id", "uname", "borrow_record"."book_id", "book_title", "borrow_date", "return_date"
                  FROM BOOKMAN."borrow_record"
                           left join BOOKMAN."user" on "user"."uid" = "borrow_record"."user_id"
                           left join BOOKMAN."book" on "book"."book_id" = "borrow_record"."book_id"
                  WHERE "borrow_record"."book_id" = #{bookId}
              ) t
     ) rt
WHERE rt.rn >= #{start} AND rt.rn <= #{end}

